using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // EF 9 breaking change: Discriminator is no longer used by default.
            // Preserve the legacy "$type" discriminator so existing documents are still readable.
            entity.HasDiscriminator<string>("$type");

            // EF 9 breaking change: id format changed from "EntityType|Key" to just "Key".
            // Preserve the legacy id format so existing documents are found.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // EF 9 breaking change: HasIndex() now throws for Cosmos.
            // Cosmos doesn't support secondary indexes via EF; remove the call.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // EF 9 breaking change: Sync I/O now throws by default for Cosmos.
    // See SyncJob.cs for the required migration to async.
