 using Microsoft.EntityFrameworkCore;
 using System.Threading.Tasks;

 class SyncJob
 {
     // EF 9 breaking change: Cosmos provider no longer supports synchronous I/O.
     // ToList() / SaveChanges() throw InvalidOperationException at runtime.
     // Migrated to async equivalents.
     async Task RunAsync(BlogContext context)
